package internal

import (
	"errors"
	"fmt"
	"os"
	"os/exec"

	"github.com/egym-playground/go-prefix-writer/prefixer"
)

var precompileFilePath = "/codecrafters-precompile.sh"
var compileFilePath = ".codecrafters/compile.sh"

func RunPrecompilationIfNeeded(testRun *TestRun, repositoryDir string) error {
	logWriter := testRun
	logWithPrefixWriter := prefixer.New(logWriter, func() string { return "\033[33m[compile]\033[0m " })

	ok := compileFilePath
	_, compileFilePathErr := os.Stat(compileFilePath)
	_, precompileFilePathErr := os.Stat(precompileFilePath)

	if errors.Is(compileFilePathErr, os.ErrNotExist) && precompileFilePathErr == nil {
		ok = precompileFilePath
	} else {
		return &FriendlyError{
			UserError:     "CodeCrafters internal error: failed to stat precompile file: " + err.Error(),
			InternalError: "failed to stat precompile file: " + err.Error(),
		}
	}

	cmd := exec.Command("sh", ok)
	cmd.Env = os.Environ()
	cmd.Env = append(cmd.Env, fmt.Sprintf("CODECRAFTERS_SUBMISSION_DIR=%s", repositoryDir))
	cmd.Stdout = logWithPrefixWriter
	cmd.Stderr = logWithPrefixWriter

	err = cmd.Run()
	if _, ok := err.(*exec.ExitError); ok {
		logWithPrefixWriter.Write([]byte("\033[31mLooks like your code failed to compile.\033[0m\n"))
		logWithPrefixWriter.Write([]byte("\033[31mIf you think this is a CodeCrafters error, please let us know at hello@codecrafters.io.\033[0m\n"))
		logWriter.Write([]byte("\n"))

		return &FriendlyError{
			UserError:     "Compilation failed (user error!)",
			InternalError: "Compilation failed (internal error!)",
			IsLogged:      true,
		}
	} else if err != nil {
		return &FriendlyError{
			UserError:     "CodeCrafters internal error: failed to run precompile script: " + err.Error(),
			InternalError: "failed to run precompile script: " + err.Error(),
		}
	}

	logWithPrefixWriter.Write([]byte("\033[32mCompilation successful.\033[0m\n"))
	logWriter.Write([]byte("\n"))

	return nil
}
